-- Reviewed D: exact classified unmatched manual/email pair. Root refreshes only its classified count-1 hash if needed.
begin isolation level repeatable read;set local lock_timeout='10s';set local statement_timeout='90s';
do $reset$ declare i1 uuid[];i2 uuid[];n bigint;h text;k1 text;k2 text;begin
lock table public.customers,public.customer_sites,public.metering_points,public.website_customer_applications,public.manual_inbound_messages,public.inbound_operation_events in share row exclusive mode;
if exists(select 1 from public.customers) or exists(select 1 from public.customer_sites) or exists(select 1 from public.metering_points) or exists(select 1 from public.website_customer_applications) then raise exception 'static_reset_source_not_empty';end if;
if exists(select 1 from pg_constraint where contype='f' and confrelid='public.manual_inbound_messages'::regclass) or exists(select 1 from pg_trigger where tgrelid='public.manual_inbound_messages'::regclass and not tgisinternal and (tgtype&8)=8) then raise exception 'static_reset_schema_changed:manual_inbound_messages';end if;
if exists(select 1 from pg_constraint where contype='f' and confrelid='public.inbound_operation_events'::regclass) or exists(select 1 from pg_trigger where tgrelid='public.inbound_operation_events'::regclass and not tgisinternal and (tgtype&8)=8) then raise exception 'static_reset_schema_changed:inbound_operation_events';end if;
select array_agg(t.id order by t.id),count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) into i1,n,h from(select t.* from public.manual_inbound_messages t where t.request_id is null and t.resolution_status='unmatched' and exists(select 1 from public.inbound_operation_events e where e.source_id=t.id::text and e.source_transport='email' and e.business_process='power_of_attorney' and e.intent='power_of_attorney_question' and e.customer_id is null and e.customer_site_id is null and e.metering_point_id is null and e.business_object_id is null) for update of t)t;
if n<>1 or h<>'38ce4b37ae7cea047f146500ef7a6d92' then raise exception 'static_reset_stale:manual_inbound_messages';end if;
select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) into k1 from public.manual_inbound_messages t where t.id<>all(coalesce(i1,'{}'::uuid[]));
select array_agg(t.id order by t.id),count(*),md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) into i2,n,h from(select t.* from public.inbound_operation_events t where t.source_transport='email' and t.business_process='power_of_attorney' and t.intent='power_of_attorney_question' and t.customer_id is null and t.customer_site_id is null and t.metering_point_id is null and t.business_object_id is null and exists(select 1 from public.manual_inbound_messages m where m.id::text=t.source_id and m.request_id is null and m.resolution_status='unmatched') and not exists(select 1 from public.ediel_messages m where m.id::text=t.source_id) for update of t)t;
if n<>1 or h<>'d9737a11a782b02e4b955d3e2aa8a427' then raise exception 'static_reset_stale:inbound_operation_events';end if;
select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) into k2 from public.inbound_operation_events t where t.id<>all(coalesce(i2,'{}'::uuid[]));
delete from public.manual_inbound_messages where id=any(i1);get diagnostics n=row_count;if n<>1 then raise exception 'static_reset_delete_mismatch:manual_inbound_messages';end if;
select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) into h from public.manual_inbound_messages t where t.id<>all(coalesce(i1,'{}'::uuid[]));if h<>k1 then raise exception 'static_reset_changed_preserved:manual_inbound_messages';end if;
delete from public.inbound_operation_events where id=any(i2);get diagnostics n=row_count;if n<>1 then raise exception 'static_reset_delete_mismatch:inbound_operation_events';end if;
select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by md5(to_jsonb(t)::text)),'')) into h from public.inbound_operation_events t where t.id<>all(coalesce(i2,'{}'::uuid[]));if h<>k2 then raise exception 'static_reset_changed_preserved:inbound_operation_events';end if;
if exists(select 1 from public.manual_inbound_messages where id=any(i1)) or exists(select 1 from public.inbound_operation_events where id=any(i2)) then raise exception 'static_reset_inbound_residual';end if;
end $reset$;commit;
select 'static_customer_reset_d_committed' as result;
